/// $INTERFACE SecureZone                               (4,4)
///     # # ----------------------------------------------------------
///     @ 0x00000 Zone_CTRL            (RW)
///               %unsigned 1  Enable                    0x0
///                                    ###
///                                    * When set, enables this Zone
///                                    * When clear, disable this Zone
///                                    ###
///               %unsigned 1  NS                        0x1
///                                    ###
///                                    * 1: this zone is non-secure
///                                    * 0: this zone is secure
///                                    ###
///               %unsigned 1  Lock                      0x0
///                                    ###
///                                    * When set, locks the registers associated with this region
///                                    * (REGION_MST_CFG, REGION_SADDR, REGION_EADDR, REGION_CTRL). Once
///                                    * set, may only be cleared by a reset
///                                    ###
///               %%        29         # Stuffing bits...
///     @ 0x00004 Master_CTRL          (RW)
///               ###
///               * Each bit represents a master
///               ###
///               %unsigned 32 S_Read_En                 0xFFFFFFFF
///                                    ###
///                                    * When set, each bit enables secure read access by the
///                                    * corresponding bus master (or master group) to the region
///                                    * 0: disable, 1: enable
///                                    ###
///     # 0x00008 Master_CTRL1         
///               %unsigned 32 S_Write_En                0xFFFFFFFF
///                                    ###
///                                    * When set, each bit enables secure write access by the
///                                    * corresponding bus master (or master group) to the region
///                                    * 0: disable, 1: enable
///                                    ###
///     # 0x0000C Master_CTRL2         
///               %unsigned 32 NS_Read_En                0xFFFFFFFF
///                                    ###
///                                    * When set, each bit enables non-secure read access by the
///                                    * corresponding bus master (or master group) to the region, if
///                                    * the region is also marked non-secure (NS) in the above control
///                                    * register
///                                    * 0: disable, 1: enable
///                                    ###
///     # 0x00010 Master_CTRL3         
///               %unsigned 32 NS_Write_En               0xFFFFFFFF
///                                    ###
///                                    * When set, each bit enables non-secure write access by the
///                                    * corresponding bus master (or master group) to the region, if
///                                    * the region is also marked non-secure (NS) in the above control
///                                    * register
///                                    * 0: disable, 1: enable
///                                    ###
///     @ 0x00014 REGION_SADDR         (RW)
///               %unsigned 32 Start_Addr                0x0
///                                    ###
///                                    * >=
///                                    ###
///     @ 0x00018 REGION_EADDR         (RW)
///               %unsigned 32 End_Addr                  0x0
///                                    ###
///                                    * <
///                                    ###
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:      28B, bits:     195b, padding:     0B
